import{at as e,it as t,n,vt as r}from"./chunks/framework.CH5tFBxi.js";import{a as i,i as a,r as o}from"./chunks/assets.B6tPA-kF.js";var s=JSON.parse(`{"title":"菜单","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"zh/menu.md","filePath":"zh/menu.md"}`),c={name:`zh/menu.md`};function l(n,s,c,l,u,d){return r(),t(`div`,null,[...s[0]||=[e(`<h1 id="菜单" tabindex="-1">菜单 <a class="header-anchor" href="#菜单" aria-label="Permalink to “菜单”">​</a></h1><p>使用 json0714 的主要入口只有两个：右键菜单和快捷键。<br> json0714 的设计宗旨是不过多干预、拦截浏览器的网络请求，仅在你需要使用时主动唤起。<br> json0714 可以在任何非 <code>New Tab</code> 页面中运行。</p><h2 id="普通右键菜单" tabindex="-1">普通右键菜单 <a class="header-anchor" href="#普通右键菜单" aria-label="Permalink to “普通右键菜单”">​</a></h2><p>在浏览器任意位置点击右键，即可看到 json0714 菜单。<br> 可使用菜单中标注的快捷键快速访问对应功能，无需依赖鼠标操作；我大部分时间都在使用快捷键。</p><p><img src="`+i+`" alt="普通右键菜单" width="702" height="724"></p><h3 id="格式化当前页面json" tabindex="-1">格式化当前页面JSON <a class="header-anchor" href="#格式化当前页面json" aria-label="Permalink to “格式化当前页面JSON”">​</a></h3><p>以当前页面显示的内容作为 JSON 输入。</p><h3 id="从剪贴板格式化json" tabindex="-1">从剪贴板格式化JSON <a class="header-anchor" href="#从剪贴板格式化json" aria-label="Permalink to “从剪贴板格式化JSON”">​</a></h3><p>以剪贴板中的内容作为 JSON 输入。</p><h3 id="复制json" tabindex="-1">复制JSON <a class="header-anchor" href="#复制json" aria-label="Permalink to “复制JSON”">​</a></h3><p>复制当前工作空间内已格式化的 JSON。<br> 复制、粘贴功能极大简化了用户与插件的交互流程，是一条提高效率的高速路。</p><h3 id="速览" tabindex="-1">速览 <a class="header-anchor" href="#速览" aria-label="Permalink to “速览”">​</a></h3><p>速览模式下，<code>[]</code> 列表节点内最多只保留 3 条数据，便于分析超大 JSON 结构。</p><h3 id="锁定" tabindex="-1">锁定 <a class="header-anchor" href="#锁定" aria-label="Permalink to “锁定”">​</a></h3><ul><li><strong>锁定当前路径</strong>：精确匹配当前页面 URL，此后浏览器访问该 URL 时，插件自动运行。</li><li><strong>锁定当前域</strong>：匹配当前页面域名，此后浏览器访问该域名时，插件自动运行。</li><li><strong>解除锁定</strong>：取消当前 URL 或当前域名的插件自动运行效果。</li></ul><h3 id="键排序" tabindex="-1">键排序 <a class="header-anchor" href="#键排序" aria-label="Permalink to “键排序”">​</a></h3><p>格式化时，按 JSON Key 的 ASCII 字典序自动排列 Key 的先后顺序。<br> 选择 <code>无</code> 时，保留原始输入顺序。</p><h3 id="更多设置" tabindex="-1">更多设置 <a class="header-anchor" href="#更多设置" aria-label="Permalink to “更多设置”">​</a></h3><p>打开设置页面，详见 <code>设置</code> 章节。</p><h2 id="右键上下文菜单" tabindex="-1">右键上下文菜单 <a class="header-anchor" href="#右键上下文菜单" aria-label="Permalink to “右键上下文菜单”">​</a></h2><p>在选中文本上点击右键，菜单中会展示 json0714 的上下文菜单。<br> 该能力不局限于 json0714 工作空间内，Chrome 浏览器中打开的任意网页均可使用。</p><p><img src="`+a+`" alt="右键上下文菜单" width="622" height="385"></p><h3 id="生成二维码" tabindex="-1">生成二维码 <a class="header-anchor" href="#生成二维码" aria-label="Permalink to “生成二维码”">​</a></h3><p>生成选中文本对应的二维码，并以弹窗展示。<br> 它是电脑端数据传输到移动端的桥梁。<br> 插件本身不限制、不校验选中文本长度，建议控制在 200 字符以内，超长可能会报错。</p><h3 id="日期-时间格式化" tabindex="-1">日期/时间格式化 <a class="header-anchor" href="#日期-时间格式化" aria-label="Permalink to “日期/时间格式化”">​</a></h3><p>尝试将选中文本转换为 <code>yyyy-MM-dd HH:mm:ss</code> 标准时间格式，方便阅读，并以弹窗展示。<br> 插件本身不对选中文本做限制或校验，支持多种时间格式，失败时会给出提示。<br> 如果有未支持的时间格式，欢迎在 <code>GitHub</code> 提需求。</p><h3 id="复制选区截图" tabindex="-1">复制选区截图 <a class="header-anchor" href="#复制选区截图" aria-label="Permalink to “复制选区截图”">​</a></h3><p>以当前选中文本区域为边界，实现浏览器内跨屏截图。相比整个页面的长截屏，粒度更细、目的性更强，也更省资源。<br> 由于浏览器策略的硬性限制，插件无法访问 iframe 中的内容，针对 iframe 的截屏会失败；此时建议使用本插件提供的 <code>在新标签页中打开框架</code> 功能，将内嵌的 iframe 在新标签页打开，iframe 就会自然转化为普通页面，新标签页内不再有截屏限制。</p><h3 id="访问选中链接" tabindex="-1">访问选中链接 <a class="header-anchor" href="#访问选中链接" aria-label="Permalink to “访问选中链接”">​</a></h3><p>尝试将选中文本作为链接在新标签页中打开。<br> 插件本身不对选中文本做限制或校验。</p><h3 id="下载选中链接" tabindex="-1">下载选中链接 <a class="header-anchor" href="#下载选中链接" aria-label="Permalink to “下载选中链接”">​</a></h3><p>尝试将选中文本作为下载链接进行下载。<br> 插件本身不对选中文本做限制或校验。</p><h2 id="右键-iframe-菜单" tabindex="-1">右键 iframe 菜单 <a class="header-anchor" href="#右键-iframe-菜单" aria-label="Permalink to “右键 iframe 菜单”">​</a></h2><p>在 iframe 框架内点击右键，菜单中会展示 json0714 的 iframe 菜单。</p><p><img src="`+o+`" alt="右键 iframe 菜单" width="670" height="343"></p><h3 id="在新标签页中打开框架" tabindex="-1">在新标签页中打开框架 <a class="header-anchor" href="#在新标签页中打开框架" aria-label="Permalink to “在新标签页中打开框架”">​</a></h3><p>将内嵌的 iframe 在新标签页打开。</p>`,37)]])}var u=n(c,[[`render`,l]]);export{s as __pageData,u as default};